---
author: 
id: F_115
internalId: 7bdf27fc-963c-4545-83e2-93410e67f0e3
title: add support for request approval
status: ready
owner: 
affects:
agents:
policy:
after: 56dd54b0-9554-4545-85d4-bb45efef4d6e
---
# Current state

`CodexStreamingAdapter` handles structured questions, but not Codex app-server approval requests. `item/fileChange/requestApproval` and `item/commandExecution/requestApproval` fall through as protocol diagnostics, for example `item/fileChange/requestApproval: unknown (...)`. No approval UI or JSON-RPC response exists, so the turn remains blocked.

# Implementation details

- Handle both approval methods as server-initiated JSON-RPC requests before notification handling. Validate request, item, thread, and turn ids; track pending requests by request id; clear them on `serverRequest/resolved`.
- Add a dedicated approval contract through `AgentRunnerService`, action execution events, Electron preload/local bridge, and remote control. Respond with `{ decision }`; for command requests, honor `availableDecisions` when supplied. Keep approvals separate from structured questions and conversation messages.
- Store pending approvals in `ActionExecutionService`. Keep execution `waitingForInput` while any question or approval remains. Replay must restore unresolved approvals and discard resolved ones after renderer reload.
- Add a separate popup approval component. Show reason plus command, working directory, parsed actions, network host/protocol, requested permissions, or affected file paths when available. Actions sit bottom-right: allow once, allow for session, decline, and stop turn. Show policy-amendment choices only when Codex supplies them.
- Support multiple pending approvals without overwriting one another. Disable a submitted request until response or resolution; reject duplicate, stale, mismatched, or unsupported decisions clearly.
- Do not persist approval requests or decisions in conversation/activity files or agent handoff context. Existing completed command/file activity remains authoritative.
- Add adapter, runner, execution-contract, bridge, remote-control, service, popup, reload, and regression tests. Run lint and tests in `desktop/` and `app/`.

# Acceptance criteria

- File-change and command-execution approval requests show actionable prompts instead of protocol diagnostics.
- Allow once/session, decline, stop-turn, and offered policy-amendment choices send the exact matching JSON-RPC decision and unblock Codex.
- Approval UI shows available security context before user decides, including network-specific context when present.
- Concurrent requests remain isolated; `serverRequest/resolved`, turn completion, or cancellation removes only matching pending requests.
- Renderer reload and remote-control clients retain correct pending approval state.
- Structured questions, activity ordering, changed-path tracking, and conversation persistence keep existing behavior; approval data is not persisted.

import { Box, Button, Stack, Typography } from '@mui/material'
import { useState } from 'react'
import type { MouseEvent } from 'react'
import type {
    AgentApprovalDecision,
    AgentCommandAction,
    AgentFileSystemPath,
} from '../../data/action_run_types'
import type { LiveAgentApproval } from '../../services/actions/action_run_registry'

const DEFAULT_APPROVAL_DECISIONS: AgentApprovalDecision[] = ['accept', 'acceptForSession', 'decline', 'cancel']

interface ActionAgentApprovalProps {
    approval: LiveAgentApproval
    onDecision: (requestId: number | string, decision: AgentApprovalDecision) => Promise<void>
}

function decisionLabel(decision: AgentApprovalDecision) {
    if (decision === 'accept') return 'Allow once'
    if (decision === 'acceptForSession') return 'Allow for session'
    if (decision === 'decline') return 'Decline'
    if (decision === 'cancel') return 'Stop turn'
    if ('acceptWithExecpolicyAmendment' in decision) return 'Allow with command policy'
    const { action, host } = decision.applyNetworkPolicyAmendment.network_policy_amendment

    return `${action === 'allow' ? 'Allow' : 'Deny'} ${host} for session`
}

function fileSystemPathLabel(path: AgentFileSystemPath) {
    if (path.type === 'path') return path.path
    if (path.type === 'glob_pattern') return path.pattern

    return path.value
}

function commandActionLabel(action: AgentCommandAction) {
    if (action.type === 'read') return `Read ${action.name}: ${action.path}`
    if (action.type === 'listFiles') return `List files${action.path ? `: ${action.path}` : ''}`
    if (action.type === 'search') {
        return `Search${action.query ? ` for ${action.query}` : ''}${action.path ? ` in ${action.path}` : ''}`
    }

    return action.command
}

function permissionLabels(approval: LiveAgentApproval) {
    const permissions = approval.additionalPermissions
    if (!permissions) return []
    const labels: string[] = []
    if (permissions.network?.enabled !== null && permissions.network?.enabled !== undefined) {
        labels.push(`Network: ${permissions.network.enabled ? 'enabled' : 'disabled'}`)
    }
    for (const path of permissions.fileSystem?.read ?? []) labels.push(`Read: ${path}`)
    for (const path of permissions.fileSystem?.write ?? []) labels.push(`Write: ${path}`)
    for (const entry of permissions.fileSystem?.entries ?? []) {
        labels.push(`${entry.access}: ${fileSystemPathLabel(entry.path)}`)
    }

    return labels
}

function approvalDetails(approval: LiveAgentApproval) {
    const details: { label: string, values: string[] }[] = []
    if (approval.command) details.push({ label: 'Command', values: [approval.command] })
    if (approval.cwd) details.push({ label: 'Working directory', values: [approval.cwd] })
    if (approval.environmentId) details.push({ label: 'Environment', values: [approval.environmentId] })
    if (approval.commandActions?.length) {
        details.push({ label: 'Actions', values: approval.commandActions.map(commandActionLabel) })
    }
    if (approval.networkApprovalContext) {
        const { host, protocol } = approval.networkApprovalContext
        details.push({ label: 'Network', values: [`${protocol}://${host}`] })
    }
    const permissions = permissionLabels(approval)
    if (permissions.length > 0) details.push({ label: 'Requested permissions', values: permissions })
    if (approval.grantRoot) details.push({ label: 'Requested write root', values: [approval.grantRoot] })
    if (approval.filePaths.length > 0) details.push({ label: 'Affected files', values: approval.filePaths })

    return details
}

/** Security context and exact provider decisions for one pending Codex approval. */
export function ActionAgentApproval({ approval, onDecision }: ActionAgentApprovalProps) {
    const [submitting, setSubmitting] = useState(false)
    const decisions = approval.availableDecisions ?? DEFAULT_APPROVAL_DECISIONS
    const disabled = submitting || approval.submitted
    const details = approvalDetails(approval)
    const handleDecisionClick = async (event: MouseEvent<HTMLButtonElement>) => {
        const decisionIndex = Number(event.currentTarget.dataset.decisionIndex)
        const decision = decisions[decisionIndex]
        if (!decision) throw new Error('Missing approval decision')
        setSubmitting(true)
        try {
            await onDecision(approval.requestId, decision)
        } catch {
            setSubmitting(false)
        }
    }

    return (
        <Stack aria-label="Agent approval" spacing={1.5} sx={{ border: 1, borderColor: 'divider', borderRadius: 1, p: 1.5 }}>
            <Stack spacing={0.5}>
                <Typography color="text.primary" variant="subtitle2">Approval required</Typography>
                {approval.reason ? <Typography color="text.secondary" variant="body2">{approval.reason}</Typography> : null}
            </Stack>
            {details.map(({ label, values }) => (
                <Stack key={label} spacing={0.25}>
                    <Typography color="text.secondary" variant="caption">{label}</Typography>
                    {values.map((value) => (
                        <Box
                            component="code"
                            key={value}
                            sx={{ color: 'text.primary', overflowWrap: 'anywhere', whiteSpace: 'pre-wrap' }}
                        >
                            {value}
                        </Box>
                    ))}
                </Stack>
            ))}
            <Stack direction="row" spacing={1} sx={{ flexWrap: 'wrap', justifyContent: 'flex-end' }}>
                {decisions.map((decision, index) => {
                    const label = decisionLabel(decision)
                    const destructive = decision === 'cancel'
                    const primary = decision === 'accept'

                    return (
                        <Button
                            color={destructive ? 'error' : 'primary'}
                            data-decision-index={index}
                            disabled={disabled}
                            key={`${index}-${label}`}
                            onClick={handleDecisionClick}
                            size="small"
                            variant={primary ? 'contained' : 'outlined'}
                        >
                            {label}
                        </Button>
                    )
                })}
            </Stack>
        </Stack>
    )
}

import type { ActionContext } from '../../data/action_context'
import type { AgentApprovalDecision, AgentApprovalRequestId } from '../../data/action_run_types'
import { actionRunRegistry, answerActionApproval } from '../../services/actions/action_run_registry'
import { dialogService } from '../../services/dialog_service'
import { useActionRunSelector } from '../hooks/use_action_runs'
import { ActionAgentApproval } from './action_agent_approval'

interface ActionAgentApprovalsProps {
    actionId: string
    context: ActionContext
}

/** Subscribes approval UI only to its bound run. */
export function ActionAgentApprovals({ actionId, context }: ActionAgentApprovalsProps) {
    const approvals = useActionRunSelector(actionId, context, (run) => run?.approvals ?? null)

    const handleDecision = async (requestId: AgentApprovalRequestId, decision: AgentApprovalDecision) => {
        const currentRunId = actionRunRegistry.getActionRunStore(actionId, context)?.getSnapshot().runId
        if (!currentRunId) return

        try {
            await answerActionApproval(currentRunId, requestId, decision)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not answer agent approval' })
            throw error
        }
    }

    return approvals?.map((approval) => (
        <ActionAgentApproval
            approval={approval}
            key={`${typeof approval.requestId}-${approval.requestId}`}
            onDecision={handleDecision}
        />
    )) ?? null
}

import type { ActionContext } from './action_context'
import type { AgentConversation, AgentConversationEventEntry, AgentConversationMessageEntry } from './data_types'
import type { ThinkingLevel } from './agent_profiles'
import type { ActionAutoFinish, ActionType } from './action_types'

export type ActionRunTerminalStatus = 'cancelled' | 'completed' | 'failed' | 'okButNotAfter'
export type ActionRunStatus = ActionRunTerminalStatus | 'queued' | 'running' | 'waitingForInput'
export type ActionRunPhase = 'after' | 'before' | 'main' | 'on'

export interface ActionRunInput {
    accessLevel?: string
    agent?: string
    approvalPolicy?: string
    continueFrom?: string
    extraPrompt?: string
    model?: string
    prompt?: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionPromptRequest {
    actionId: string
    context: ActionContext
}

export interface PreparedActionPrompt {
    prompt: string
}

export interface ActionStartRequest {
    actionId: string
    context: ActionContext
    runInput: ActionRunInput
}

export interface AgentQuestionOption {
    description?: string
    label: string
}

export interface AgentQuestion {
    header: string
    id: string
    isOther?: boolean
    isSecret?: boolean
    options?: AgentQuestionOption[] | null
    question: string
}

export type AgentApprovalRequestId = number | string
export type AgentNetworkProtocol = 'http' | 'https' | 'socks5Tcp' | 'socks5Udp'
export type AgentFileSystemPath =
    | { path: string, type: 'path' }
    | { pattern: string, type: 'glob_pattern' }
    | { type: 'special', value: string }
export interface AgentAdditionalPermissions {
    fileSystem: {
        entries?: { access: 'deny' | 'read' | 'write', path: AgentFileSystemPath }[]
        read: string[] | null
        write: string[] | null
    } | null
    network: { enabled: boolean | null } | null
}
export type AgentCommandAction =
    | { command: string, name: string, path: string, type: 'read' }
    | { command: string, path: string | null, type: 'listFiles' }
    | { command: string, path: string | null, query: string | null, type: 'search' }
    | { command: string, type: 'unknown' }
export interface AgentNetworkPolicyAmendment {
    action: 'allow' | 'deny'
    host: string
}
export type AgentApprovalDecision =
    | 'accept'
    | 'acceptForSession'
    | 'cancel'
    | 'decline'
    | { acceptWithExecpolicyAmendment: { execpolicy_amendment: string[] } }
    | { applyNetworkPolicyAmendment: { network_policy_amendment: AgentNetworkPolicyAmendment } }
export interface AgentApproval {
    additionalPermissions?: AgentAdditionalPermissions | null
    approvalId?: string | null
    availableDecisions?: AgentApprovalDecision[] | null
    command?: string | null
    commandActions?: AgentCommandAction[] | null
    cwd?: string | null
    environmentId?: string | null
    filePaths: string[]
    grantRoot?: string | null
    itemId: string
    kind: 'commandExecution' | 'fileChange'
    networkApprovalContext?: { host: string, protocol: AgentNetworkProtocol } | null
    proposedExecpolicyAmendment?: string[] | null
    proposedNetworkPolicyAmendments?: AgentNetworkPolicyAmendment[] | null
    reason?: string | null
    requestId: AgentApprovalRequestId
    startedAtMs: number
    threadId: string
    turnId: string
}

interface ActionRunEventBase {
    actionId: string
    actionType?: ActionType
    autoFinish?: ActionAutoFinish | null
    context: ActionContext
    runId: string
    interactionReady?: boolean
    phase: ActionRunPhase
    rootActionId: string
    sequence?: number
    streaming?: boolean
}

export type ActionRunUpdate =
    | {
        continued?: boolean
        conversation: AgentConversation
        kind: 'agentStarted'
    }
    | {
        conversation: AgentConversation
        kind: 'agentClosed'
    }
    | {
        kind: 'agentQuestion'
        questions: AgentQuestion[]
        requestId: number | string | null
    }
    | {
        approval: AgentApproval
        kind: 'agentApproval'
    }
    | {
        kind: 'agentApprovalResolved' | 'agentApprovalSubmitted'
        requestId: AgentApprovalRequestId
    }
    | {
        kind: 'agentQuestionAnswer' | 'agentUserMessage'
        userMessage: AgentConversationMessageEntry
    }
    | {
        event: AgentConversationEventEntry
        kind: 'agentEvent'
    }
    | {
        command?: string
        content: string
        kind: 'error' | 'output'
        messageId?: string
        sequence?: number
    }

export type ActionRunEvent =
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'run'
    }
    | ActionRunEventBase & {
        command?: string
        conversationId?: string
        runWorktree?: number | null
        message?: string | null
        accessLevel?: string
        approvalPolicy?: string
        reference?: string
        status: ActionRunStatus
        thinkingLevel?: ThinkingLevel
        type: 'action'
    }
    | ActionRunEventBase & {
        status: 'running' | 'waitingForInput'
        type: 'agentState'
    }
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'update'
        update: ActionRunUpdate
    }

export interface ActionRunLogEntry {
    accessLevel?: string
    actionId: string
    actionName: string
    approvalPolicy?: string
    command: string | null
    message: string
    phase: ActionRunPhase
    status: ActionRunStatus
    stderr: string
    stdout: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionRunResult {
    logs: ActionRunLogEntry[]
    status: ActionRunStatus
}

