        md2Actions?: ElectronActionBridge
    }
}

let actionBridgeOverride: ElectronActionBridge | null = null

export function setActionBridgeOverride(bridge: ElectronActionBridge | null) {
    actionBridgeOverride = bridge
}

export function getElectronActionBridge() {
    if (actionBridgeOverride) return actionBridgeOverride

    return window.md2Actions ?? null
}

export function hasActionRunBackend() {
    return getElectronActionBridge() !== null
}

const { ActionCancellationError } = require('./action_cancellation_error');
const { executeCommandAction } = require('./action_command_executor');
const { ActionPhaseError } = require('./action_phase_error');
const { runWithGitOperationContext } = require('../../git/git_operation_context');
const {
    captureCommitReferences,
    combineOutput,
    createAgentHistoryEntry,
    createCommandHistoryEntry,
} = require('./action_run_history');

function errorMessage(error, fallback) {
    return error instanceof Error ? error.message : fallback;
}

class ActionRun {
    constructor(snapshot, dependencies) {
        this.actionsFolder = snapshot.actionsFolder;
        this.activityOrigin = snapshot.activityOrigin;
        this.context = snapshot.context;
        this.runId = snapshot.runId;
        this.project = snapshot.project;
        this.projectFolder = snapshot.projectFolder;
        this.releasesFolder = snapshot.releasesFolder;
        this.rootAction = snapshot.rootAction;
        this.runInput = snapshot.runInput;
        this.startedAt = snapshot.startedAt;
        this.actionWorktreeRunService = dependencies.actionWorktreeRunService;
        this.agentExecutor = dependencies.agentExecutor;
        this.agentRunnerService = dependencies.agentRunnerService;
        this.commandRunner = dependencies.commandRunner;
        this.localGitService = dependencies.localGitService;
        this.publisher = dependencies.publisher;
        this.activeAction = null;
        this.activeAgentRunId = null;
        this.activeAgentQuestion = false;
        this.activeAgentApprovals = new Map();
        this.autoFinishPending = false;
        this.commitReferenceKeys = new Set();
        this.commitReferences = [];
        this.conversationIds = [];
        this.completion = null;
        this.controller = new AbortController();
        this.rootHistoryEntry = null;
        this.nextEventSequence = 1;
    }

    start(finalize) {
        const runCompletion = this.run();
        this.completion = finalize(runCompletion);
    }

    cancel() {
        this.controller.abort();
        if (this.activeAgentRunId) this.agentRunnerService.stop(this.activeAgentRunId);
    }

    suspend() {
        this.controller.abort();
        if (this.activeAgentRunId) this.agentRunnerService.suspend(this.activeAgentRunId);
    }

    sendAgentMessage(content) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        if (this.activeAgentQuestion) throw new Error('Answer pending structured question before sending queued prompt');
        if (this.activeAgentApprovals.size > 0) throw new Error('Answer pending approval before sending queued prompt');
        return this.agentRunnerService.sendMessage(this.activeAgentRunId, content);
    }

    beginAgentPromptDraft() {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);

        return this.agentRunnerService.beginQueuedMessageDraft(this.activeAgentRunId);
    }

    setAgentQueuedMessage(sessionId, content, revision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);

        return this.agentRunnerService.setQueuedMessage(this.activeAgentRunId, sessionId, content, revision);
    }

    sendQueuedAgentMessage(sessionId, revision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);
        if (this.activeAgentQuestion) throw new Error('Answer pending structured question before sending queued prompt');
        if (this.activeAgentApprovals.size > 0) throw new Error('Answer pending approval before sending queued prompt');
        return this.agentRunnerService.sendQueuedMessage(this.activeAgentRunId, sessionId, revision);
    }

    async answerAgentQuestion(requestId, answers) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        await this.agentRunnerService.answerQuestion(this.activeAgentRunId, requestId, answers);
        this.activeAgentQuestion = false;
    }

    answerAgentApproval(requestId, decision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        if (!this.activeAgentApprovals.has(requestId)) throw new Error(`Unknown or stale action approval request id: ${requestId}`);

        return this.agentRunnerService.answerApproval(this.activeAgentRunId, requestId, decision);
    }

    finishAgent() {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        this.agentRunnerService.finish(this.activeAgentRunId);
    }

    handleCardStateChange(cardInternalId, state) {
        if (this.context.cardInternalId !== cardInternalId) return;
        if (
            this.activeAction?.type !== 'agent'
            || !this.activeAction.streaming
            || this.activeAction.autoFinish?.state !== state
        ) return;
        if (this.activeAgentRunId) {
            this.agentRunnerService.finish(this.activeAgentRunId);
            return;
        }

        this.autoFinishPending = true;
    }

    async run() {
        return runWithGitOperationContext({ runId: this.runId }, () => this.runWithContext());
    }

    async runWithContext() {
        this.publish(this.rootAction, 'main', 'running', { type: 'run' });
        let status = 'completed';
        let failure = null;
        try {
            const onQueued = () => this.publish(this.rootAction, 'main', 'queued', { type: 'action' });
            const lockOptions = { onQueued, signal: this.controller.signal };
            await this.actionWorktreeRunService.runWithCardLock(
                this.project,
                this.context,
                () => this.runAction(this.rootAction, 'main', true),
                lockOptions,
            );
        } catch (error) {
            failure = error;
            if (error instanceof ActionCancellationError || this.controller.signal.aborted) status = 'cancelled';
            else status = error instanceof ActionPhaseError && error.rootPhase === 'after' ? 'okButNotAfter' : 'failed';
        }

        try {
            await this.persistRootActivity(status, failure);
        } catch (error) {
            failure = error;
            status = 'failed';
            const message = errorMessage(error, `${this.rootAction.label} history recording failed`);
            this.publish(this.rootAction, 'main', 'failed', { message, type: 'action' });
        }

        const result = {
            runId: this.runId,
            failure: failure ? errorMessage(failure, 'Action failed') : null,
            status,
        };
        this.publish(this.rootAction, 'main', status, { message: result.failure, type: 'run' });

        return result;
    }

    async runAction(action, phase, isRoot = false, rootPhase = phase) {
        this.throwIfCancelled();
        for (const beforeAction of action.onBefore) {
            await this.runAction(beforeAction, 'before', false, isRoot ? 'before' : rootPhase);
        }

        const output = await this.runMain(action, phase, isRoot, rootPhase);
        const matches = action.on.filter((rule) => new RegExp(rule.condition, 'u').test(output));
        for (const rule of matches) await this.runAction(rule.action, 'on', false, isRoot ? 'on' : rootPhase);

        for (const afterAction of action.onAfter) {
            await this.runAction(afterAction, 'after', false, isRoot ? 'after' : rootPhase);
        }

        return output;
    }

    async runMain(action, phase, isRoot, rootPhase) {
        this.throwIfCancelled();
        this.activeAction = action;
        this.autoFinishPending = false;

        try {
            const result = await this.executeAction(action, phase, isRoot);
            if (this.controller.signal.aborted) {
                this.publish(action, phase, 'cancelled', {
                    command: Array.isArray(result.command) ? result.command.join(' ') : result.command,
                    runWorktree: result.runWorktree,
                    message: 'Action cancelled',
                    accessLevel: result.accessLevel,
                    approvalPolicy: result.approvalPolicy,
                    reference: result.reference,
                    conversationId: result.conversationId,
                    thinkingLevel: result.thinkingLevel,
                    type: 'action',
                });
                const cancellationError = new ActionCancellationError('Action cancelled');
                cancellationError.terminalEventEmitted = true;
                throw cancellationError;
            }

            const status = result.exitCode === 0 ? 'completed' : 'failed';
            const output = combineOutput(result);
            this.publish(action, phase, status, {
                command: Array.isArray(result.command) ? result.command.join(' ') : result.command,
                runWorktree: result.runWorktree,
                message: status === 'completed' ? `${action.label} completed` : `${action.label} failed with exit code ${result.exitCode}`,
                accessLevel: result.accessLevel,
                approvalPolicy: result.approvalPolicy,
                reference: result.reference,
                conversationId: result.conversationId,
                thinkingLevel: result.thinkingLevel,
                type: 'action',
            });
            this.clearActiveAction(action);
            if (result.exitCode !== 0) throw new ActionPhaseError(`${action.label} failed with exit code ${result.exitCode}`, phase, rootPhase);

            return output;
        } catch (error) {
            this.clearActiveAction(action);
            if (error instanceof ActionCancellationError || this.controller.signal.aborted) {
                if (!error?.terminalEventEmitted) this.publish(action, phase, 'cancelled', { message: 'Action cancelled', type: 'action' });
                throw new ActionCancellationError('Action cancelled');
            }
            if (error instanceof ActionPhaseError) throw error;

            const message = errorMessage(error, `${action.label} failed`);
            this.publish(action, phase, 'failed', { message, type: 'action' });
            throw new ActionPhaseError(message, phase, rootPhase, error);
        }
    }

    clearActiveAction(action) {
        if (this.activeAction !== action) return;
        this.activeAction = null;
        this.autoFinishPending = false;
    }

    async executeAction(action, phase, isRoot) {
        if (action.type === 'command' && isRoot && this.runInput.continueFrom) {
            throw new Error('Conversation continuation requires an agent action');
        }
        if (action.autoFinish && (
            this.context.kind !== 'card'
            || typeof this.context.cardInternalId !== 'string'
            || this.context.cardInternalId.length === 0
        )) {
            throw new Error(`Action "${action.label}" requires card context for autoFinish`);
        }

        return this.actionWorktreeRunService.execute(this.project, action, this.context, async (project) => {
            this.publish(action, phase, 'running', { type: 'action' });
            const result = action.type === 'agent'
                ? await this.executeAgentAction(action, phase, isRoot, project)
                : await this.executeCommandAction(action, phase, isRoot, project);
            const committedResult = await this.commitTrackedAgentChanges(project, action, result);
            const runProject = {
                ...project,
                branch: committedResult.branch ?? project.branch,
                rootPath: committedResult.repositoryRoot ?? project.rootPath,
            };
            const historyInput = {
                action,
                context: this.context,
                project: runProject,
                projectFolder: this.projectFolder,
                result: committedResult,
            };
            const entry = action.type === 'agent'
                ? createAgentHistoryEntry(historyInput)
                : createCommandHistoryEntry(historyInput);
            const commitReferences = await captureCommitReferences(this.localGitService, historyInput);
            this.collectCommitReferences(commitReferences);
            if (isRoot) this.rootHistoryEntry = entry;
            if (action.type === 'agent' && typeof committedResult.conversationId === 'string') {
                this.conversationIds.push(committedResult.conversationId);
            }

            return committedResult;
        });
    }

    collectCommitReferences(references) {
        for (const reference of references) {
            const key = `${reference.repositoryRoot}\0${reference.commit}`;
            if (this.commitReferenceKeys.has(key)) continue;
            this.commitReferenceKeys.add(key);
            this.commitReferences.push(reference);
        }
    }

    async persistRootActivity(status, failure) {
        const completedAt = new Date().toISOString();
        const commits = this.commitReferences.map((reference) => {
            const persisted = Object.fromEntries(Object.entries(reference).filter(([fieldName]) => fieldName !== 'repositoryRoot'));
            if (reference.actionId === this.rootAction.id) {
                delete persisted.actionId;
                delete persisted.actionName;
            }

            return persisted;
        });
        const history = this.rootHistoryEntry
            ?? { completedAt, output: failure ? errorMessage(failure, 'Action failed') : '', prompt: '', status: 'failed' };
        const record = {
            commits,
            completedAt,
            conversationIds: [...new Set(this.conversationIds)],
            runId: this.runId,
            history,
            origin: this.activityOrigin,
            rootActionId: this.rootAction.id,
            rootActionLabel: this.rootAction.label,
            startedAt: this.startedAt,
            status,
        };
        await this.localGitService.appendAndCommitActionActivity(
            this.project,
            this.projectFolder,
            this.activityOrigin,
            record,
            `Record ${this.rootAction.label} activity`,
        );
    }

    async commitTrackedAgentChanges(project, action, result) {
        if (action.type !== 'agent' || !action.trackFileChanges) return result;
        if (result.exitCode !== 0 || this.controller.signal.aborted) return result;
        const changedPaths = result.changedPaths ?? [];
        if (changedPaths.length === 0) return result;
        const trackedCommit = await this.localGitService.commitTrackedPaths(
            project.rootPath,
            changedPaths,
            action.label,
            this.controller.signal,
        );

        return { ...result, trackedCommit };
    }

    executeCommandAction(action, phase, isRoot, project) {
        const onOutput = ({ command, stderr, stdout }) => {
            if (stdout.length > 0) this.publish(action, phase, 'running', { type: 'update', update: { command, content: stdout, kind: 'output' } });
            if (stderr.length > 0) this.publish(action, phase, 'running', { type: 'update', update: { command, content: stderr, kind: 'error' } });
        };

        return executeCommandAction({
            action,
            commandRunner: this.commandRunner,
            context: this.context,
            extraPrompt: isRoot ? this.runInput.extraPrompt : '',
            onOutput,
            primaryProject: this.project,
            project,
            releasesFolder: this.releasesFolder,
            signal: this.controller.signal,
        });
    }

    async executeAgentAction(action, phase, isRoot, project) {
        const onActiveRunChange = (runId) => {
            this.activeAgentRunId = runId;
            if (runId) {
                this.publish(action, phase, 'running', { interactionReady: true, type: 'agentState' });
                if (this.autoFinishPending) {
                    this.autoFinishPending = false;
                    this.agentRunnerService.finish(runId);
                }
            }
            else {
                this.activeAgentQuestion = false;
                this.activeAgentApprovals.clear();
                this.publish(action, phase, 'running', { interactionReady: false, type: 'agentState' });
            }
        };
        const onEvent = (agentEvent) => {
            if (agentEvent.type === 'started') {
                const { continued, conversation } = agentEvent;
                const update = { continued, conversation, kind: 'agentStarted' };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'closed') {
                const update = { conversation: agentEvent.conversation, kind: 'agentClosed' };
                this.publish(action, phase, agentEvent.conversation.status, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'state') {
                this.publish(action, phase, agentEvent.state, { interactionReady: true, type: 'agentState' });
                return;
            }
            if (agentEvent.type === 'question') {
                this.activeAgentQuestion = true;
                const update = {
                    kind: 'agentQuestion',
                    questions: agentEvent.questions,
                    requestId: agentEvent.requestId,
                };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'userMessage') {
                this.activeAgentQuestion = false;
                const update = { kind: 'agentUserMessage', userMessage: agentEvent.userMessage };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'questionAnswered') {
                this.activeAgentQuestion = false;
                const update = { kind: 'agentQuestionAnswer', userMessage: agentEvent.userMessage };
                this.publish(action, phase, agentEvent.state, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approval') {
                this.activeAgentApprovals.set(agentEvent.approval.requestId, { ...agentEvent.approval, submitted: false });
                const update = { approval: agentEvent.approval, kind: 'agentApproval' };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approvalSubmitted') {
                const approval = this.activeAgentApprovals.get(agentEvent.requestId);
                if (!approval) return;
                approval.submitted = true;
                const update = { kind: 'agentApprovalSubmitted', requestId: agentEvent.requestId };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approvalResolved') {
                if (!this.activeAgentApprovals.delete(agentEvent.requestId)) return;
                const update = { kind: 'agentApprovalResolved', requestId: agentEvent.requestId };
                this.publish(action, phase, agentEvent.state, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'agentEvent') {
                const update = { event: agentEvent.event, kind: 'agentEvent' };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }

            const update = {
                content: agentEvent.content,
                kind: agentEvent.type,
                ...(agentEvent.messageId !== undefined ? { messageId: agentEvent.messageId } : {}),
                ...(agentEvent.sequence !== undefined ? { sequence: agentEvent.sequence } : {}),
            };
            this.publish(action, phase, 'running', { type: 'update', update });
        };
        const runInput = isRoot ? this.runInput : { extraPrompt: '' };

        const input = {
            action,
            activityOrigin: this.activityOrigin,
            context: this.context,
            runId: this.runId,
            onActiveRunChange,
            onEvent,
            project,
            projectFolder: this.projectFolder,
            primaryProject: this.project,
            releasesFolder: this.releasesFolder,
            runInput,
            signal: this.controller.signal,
        };
        let result = await this.agentExecutor.execute(input);
        const changedPaths = new Set(result.changedPaths ?? []);
        let stderr = result.stderr ?? '';
        let stdout = result.stdout ?? '';
        while (result.exitCode === 0 && result.queuedMessage) {
            const queuedMessage = result.queuedMessage;
            result = await this.agentExecutor.execute({
                ...input,
                runInput: {
                    ...runInput,
                    continueFrom: result.reference,
                    prompt: queuedMessage,
                },
            });
            for (const changedPath of result.changedPaths ?? []) changedPaths.add(changedPath);
            stderr += result.stderr ?? '';
            stdout += result.stdout ?? '';
        }

        return { ...result, changedPaths: [...changedPaths], stderr, stdout };
    }

    publish(action, phase, status, details) {
        const event = {
            actionId: action.id,
            actionType: action.type,
            autoFinish: action.autoFinish ?? null,
            context: this.context,
            runId: this.runId,
            interactionReady: details.interactionReady ?? false,
            phase,
            rootActionId: this.rootAction.id,
            status,
            streaming: action.type === 'agent' && action.streaming,
            ...details,
            sequence: this.nextEventSequence,
        };
        this.nextEventSequence += 1;
        this.publisher(event);
    }

    throwIfCancelled() {
        if (this.controller.signal.aborted) throw new ActionCancellationError('Action cancelled');
    }
}

module.exports = { ActionRun };

const { resolveAgentCommand } = require('../actions/agent/agent_profiles.mjs');

const INTEGRATION_ACTIVITY_LABEL = 'Integrate into project';
const SEARCH_AGENT_PROMPT_PREFIX = 'Return only a single JavaScript-compatible regular expression pattern (no explanation, no surrounding text or markdown) that matches the following search request:\n\n';

function cardIntegrationTracking(request) {
    const hasCardInternalId = Object.hasOwn(request, 'cardInternalId');
    const hasProjectFolder = Object.hasOwn(request, 'projectFolder');
    if (!hasCardInternalId && !hasProjectFolder) return null;
    if (typeof request.cardInternalId !== 'string' || request.cardInternalId.length === 0) {
        throw new Error('Missing worktree integration cardInternalId');
    }
    if (typeof request.projectFolder !== 'string') throw new Error('Missing worktree integration projectFolder');

    return { cardInternalId: request.cardInternalId, projectFolder: request.projectFolder };
}

function errorMessage(error) {
    return error instanceof Error ? error.message : String(error);
}

function resolveSearchAgent(config) {
    const resolved = resolveAgentCommand(config);

    return {
        agent: resolved.agent,
        command: resolved.command,
    };
}

function createLocalBridgeDispatch(dependencies) {
    const {
        actionRunnerService,
        actionSchedulerService,
        agentExecutableAvailability,
        agentRunnerService,
        codexRuntimeService,
        desktopConfigStore,
        diffService,
        localGitService,
        openProjectFolder,
        openWorktreeFolder,
        readDesktopConfig,
        worktreeService,
    } = dependencies;
    let currentLocalProject = null;

    function isCurrentProject(project) {
        return !!currentLocalProject
            && currentLocalProject.branch === project.branch
            && currentLocalProject.id === project.id
            && currentLocalProject.rootPath === project.rootPath;
    }

    async function activateProject(project) {
        if (isCurrentProject(project)) return;

        currentLocalProject = project;
        if (actionSchedulerService) await actionSchedulerService.startProject(project);
        await worktreeService.startProject(project);
    }

    const dataBridge = {
        checkoutBranch: async (project, branch) => {
            const checkedOutProject = await localGitService.checkoutBranch(project, branch);
            await activateProject(checkedOutProject);

            return currentLocalProject;
        },
        cancelActionSchedule: (project, actionsFolder, scheduleId) => {
            if (actionSchedulerService) return actionSchedulerService.cancelActionSchedule(scheduleId);

            return localGitService.cancelActionSchedule(project, actionsFolder, scheduleId);
        },
        commit: async (request) => {
            await localGitService.commit(request, currentLocalProject);

            return [];
        },
        createProject: async (project, workingFolder) => {
            const createdProject = await localGitService.createProject(project, workingFolder);
            await activateProject(createdProject);

            return currentLocalProject;
        },
        deleteFile: (request) => localGitService.deleteFile(request, currentLocalProject),
        deleteFolder: (request) => localGitService.deleteFolder(request, currentLocalProject),
        getActiveProject: () => currentLocalProject,
        hasPendingPush: (project) => localGitService.hasPendingPush(project),
        listBranches: (project) => localGitService.listBranches(project),
        listAgentConversationReferences: (project, projectFolder) => (
            localGitService.listAgentConversationReferences(project, projectFolder)
        ),
        listRepositoryFiles: (project) => localGitService.listRepositoryFiles(project),
        listTopLevelFolders: (project) => localGitService.listTopLevelFolders(project),
        loadActionFiles: (project, actionsFolder) => localGitService.loadActionFiles(project, actionsFolder),
        loadActionSchedules: (project, actionsFolder) => localGitService.loadActionSchedules(project, actionsFolder),
        loadAgentConversation: async (reference) => {
            return localGitService.loadAgentConversation(currentLocalProject, reference);
        },
        loadAgentAvailability: () => {
            const { agentProfiles } = readDesktopConfig(desktopConfigStore);

            return agentExecutableAvailability(agentProfiles);
        },
        loadFile: (project, path) => localGitService.loadFile(project, path),
        loadProjectAsset: (project, path) => localGitService.loadProjectAsset(project, path),
        loadProject: async (project, workingFolder) => {
            await activateProject(project);

            return localGitService.loadProject(project, workingFolder);
        },
        loadProjectConfig: (project) => localGitService.loadProjectConfig(project),
        loadProjectRoot: async (project, workingFolder) => {
            await activateProject(project);

            return localGitService.loadProjectRoot(project, workingFolder);
        },
        moveFiles: (request) => localGitService.moveFiles(request, currentLocalProject),
        openProjectFolder: async () => {
            if (!openProjectFolder) throw new Error('Project folder picker is not available');

            const rootPath = await openProjectFolder();
            if (!rootPath) return null;

            const project = await localGitService.resolveLocalProject(rootPath);
            await activateProject(project);

            return project;
        },
        addWorktree: async (project) => {
            if (!openWorktreeFolder) throw new Error('Worktree folder picker is not available');

            const folderPath = await openWorktreeFolder();
            if (!folderPath) return false;

            await worktreeService.add(project, folderPath);

            return true;
        },
        prepareWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree preparation request');

            return worktreeService.prepare(request.project, request.worktree, request.branchName);
        },
        commitWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree commit request');

            return worktreeService.commit(request.project, request.worktree, request.message);
        },
        discardWorktreeChanges: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree discard request');

            return worktreeService.discard(request.project, request.worktree);
        },
        integrateWorktree: async (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree integration request');
            const tracking = cardIntegrationTracking(request);
            const integration = await worktreeService.integrate(request.project, request.worktree);
            if (!tracking) return;

            try {
                if (!integration || typeof integration.commit !== 'string' || typeof integration.branch !== 'string') {
                    throw new Error('Worktree integration returned no commit metadata');
                }
                const metadata = await localGitService.resolveCommitMetadata(request.project.rootPath, integration.commit);
                const origin = { cardInternalId: tracking.cardInternalId, kind: 'card' };
                const commit = { ...metadata, branch: integration.branch };
                const record = {
                    commits: [commit],
                    completedAt: metadata.committedAt,
                    label: INTEGRATION_ACTIVITY_LABEL,
                    origin,
                    type: 'system',
                };
                await localGitService.appendAndCommitSystemActivity(
                    request.project,
                    tracking.projectFolder,
                    origin,
                    record,
                    `Record ${INTEGRATION_ACTIVITY_LABEL} activity`,
                );
            } catch (error) {
                throw new Error(`Worktree integrated, but card history tracking failed: ${errorMessage(error)}`, { cause: error });
            }
            try {
                await worktreeService.synchronize(request.project, request.worktree);
            } catch (error) {
                throw new Error(`Worktree integrated and card history tracked, but linked worktree synchronization failed: ${errorMessage(error)}`, { cause: error });
            }
        },
        parkWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree parking request');

            return worktreeService.park(request.project, request.worktree);
        },
        pullWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree pull request');

            return worktreeService.pull(request.project, request.worktree);
        },
        pull: (project) => worktreeService.pullPrimary(project),
        push: async (project) => {
            await localGitService.push(project);
            await worktreeService.refreshLocal();
        },
        pushWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree push request');

            return worktreeService.push(request.project, request.worktree);
        },
        rebaseWorktree: (request) => {
            if (!request || typeof request !== 'object') throw new Error('Missing worktree rebase request');

            return worktreeService.rebase(request.project, request.worktree);
        },
        onWorktreesChanged: (callback) => worktreeService.subscribe(callback),
        refreshWorktrees: (project) => worktreeService.refreshRemote(project),
        resolveProject: async (project) => {
            const resolvedProject = await localGitService.resolveLocalProject(project.rootPath);
            await activateProject(resolvedProject);

            return resolvedProject;
        },
        saveActionSchedules: (project, actionsFolder, schedules) => localGitService.saveActionSchedules(project, actionsFolder, schedules),
        saveProjectConfig: (project, config) => localGitService.saveProjectConfig(project, config),
        removeWorktree: (project, folderPath) => worktreeService.remove(project, folderPath),
        stopAgent: (runId) => agentRunnerService.stop(runId),
        watchProject: (project, callback) => localGitService.watchProject(project, (event) => {
            if (actionSchedulerService) void actionSchedulerService.handleProjectChange(event);
            callback(event);
        }),
    };

    const actionBridge = {
        answerActionApproval: (runId, requestId, decision) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.answerAgentApproval(runId, requestId, decision);
        },
        answerActionQuestion: (runId, requestId, answers) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.answerAgentQuestion(runId, requestId, answers);
        },
        beginActionPromptDraft: (runId) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.beginAgentPromptDraft(runId);
        },
        generateDiff: async (request) => {
            const result = await diffService.generateDiff(currentLocalProject, request);

            return { ...result, repositoryRoot: currentLocalProject.rootPath };
        },
        loadActionRunHistory: async (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            const projectFolder = actionRunnerService.requireProjectFolder();
            const historyRequest = { ...request, projectFolder };

            return localGitService.loadActionRunHistory(currentLocalProject, historyRequest);
        },
        loadActiveActionRunEvents: () => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.loadActiveRunEvents();
        },
        notifyActionCardStateChange: (cardInternalId, state) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.handleCardStateChange(cardInternalId, state);
        },
        loadCardActivity: async (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');
            if (!request || typeof request.cardInternalId !== 'string' || request.cardInternalId.length === 0) {
                throw new Error('Missing card activity cardInternalId');
            }
            const projectFolder = actionRunnerService.requireProjectFolder();
            const worktrees = worktreeService.getRecords(currentLocalProject);

            return localGitService.loadCardActivity(currentLocalProject, projectFolder, request.cardInternalId, worktrees);
        },
        loadAgentAvailability: () => {
            const { agentProfiles } = readDesktopConfig(desktopConfigStore);

            return agentExecutableAvailability(agentProfiles);
        },
        cancelActionRun: (runId) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.cancel(runId);
        },
        finishActionRun: (runId) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.finishAgentRun(runId);
        },
        onActionRun: (callback) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.subscribe(callback);
        },
        openInEditor: async (request) => diffService.openInEditor(currentLocalProject, request),
        prepareActionPrompt: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.prepareActionPrompt(request);
        },
        readFileAtCommit: (request) => localGitService.readFileAtCommit(currentLocalProject, request),
        registerActionSchedule: (request) => {
            if (!actionSchedulerService) throw new Error('Action scheduler is not available');

            return actionSchedulerService.registerActionSchedule(request);
        },
        runSearchRegexpAgent: async (input, callback) => {
            if (typeof input !== 'string' || input.length === 0) throw new Error('Missing regular expression search input');

            const resolved = resolveSearchAgent(readDesktopConfig(desktopConfigStore));
            const projectConfig = await localGitService.loadProjectConfig(currentLocalProject);
            const projectFolder = typeof projectConfig?.projectFolder === 'string' ? projectConfig.projectFolder : '';
            const request = {
                agent: resolved.agent,
                activityOrigin: { kind: 'project' },
                activityProject: currentLocalProject,
                command: resolved.command,
                prompt: `${SEARCH_AGENT_PROMPT_PREFIX}${input}`,
                projectFolder,
                title: 'Search RegExp',
            };
            const result = await agentRunnerService.run(currentLocalProject, request, callback);

            return result.stdout;
        },
        sendActionMessage: (runId, content) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.sendAgentMessage(runId, content);
        },
        sendActionQueuedMessage: (runId, sessionId, revision) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.sendQueuedAgentMessage(runId, sessionId, revision);
        },
        setActionQueuedMessage: (runId, sessionId, content, revision) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.setAgentQueuedMessage(runId, sessionId, content, revision);
        },
        startAction: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.start(request);
        },
        startUnattendedAction: (request) => {
            if (!actionRunnerService) throw new Error('Action runner is not available');

            return actionRunnerService.start(request, { interactive: false });
        },
    };

    const codexRuntimeBridge = {
        getCodexRateLimits: () => codexRuntimeService?.getSnapshot() ?? null,
        onCodexRateLimits: (callback) => {
            if (!codexRuntimeService) throw new Error('Codex runtime service is not available');

            return codexRuntimeService.subscribe(callback);
        },
    };

    const methods = { ...dataBridge, ...actionBridge, ...codexRuntimeBridge };

    return {
        actionBridge,
        codexRuntimeBridge,
        dataBridge,
        invoke: (method, params = []) => {
            const handler = methods[method];
            if (!handler) throw new Error(`Unknown remote-control method: ${method}`);
            if (!Array.isArray(params)) throw new Error('Remote-control params must be an array');

            return handler(...params);
        },
    };
}

module.exports = { createLocalBridgeDispatch };

