export interface AgentInput {
  /**
   * A short (3-5 word) description of the task
   */
  description: string;
  /**
   * The task for the agent to perform
   */
  prompt: string;
  /**
   * The type of specialized agent to use for this task
   */
  subagent_type?: string;
  /**
   * Optional model override for this agent. Takes precedence over the agent definition's model frontmatter. If omitted, uses the agent definition's model, or inherits from the parent. Ignored for subagent_type: "fork" â€” forks always inherit the parent model.
   */
  model?: "sonnet" | "opus" | "haiku" | "fable";
  /**
   * Set to true to run this agent in the background. You will be notified when it completes.
   */
  run_in_background?: boolean;
  /**
   * Name for the spawned agent. Makes it addressable via SendMessage({to: name}) while running.
   */
  name?: string;
  /**
   * Team name for spawning. Uses current team context if omitted.
   */
  team_name?: string;
  /**
   * Permission mode for spawned teammate (e.g., "plan" to require plan approval).
   */
  mode?: "acceptEdits" | "auto" | "bypassPermissions" | "default" | "dontAsk" | "plan";
  /**
   * Isolation mode. "worktree" creates a temporary git worktree so the agent works on an isolated copy of the repo.
   */
  isolation?: "worktree";
}
export interface BashInput {
  /**
   * The command to execute
   */
  command: string;
  /**
   * Optional timeout in milliseconds (max 600000)
   */
  timeout?: number;
  /**
   * Clear, concise description of what this command does in active voice. Never use words like "complex" or "risk" in the description - just describe what it does.
   *
   * For simple commands (git, npm, standard CLI tools), keep it brief (5-10 words):
   * - ls â†’ "List files in current directory"
   * - git status â†’ "Show working tree status"
   * - npm install â†’ "Install package dependencies"
   *
   * For commands that are harder to parse at a glance (piped commands, obscure flags, etc.), add enough context to clarify what it does:
   * - find . -name "*.tmp" -exec rm {} \; â†’ "Find and delete all .tmp files recursively"
   * - git reset --hard origin/main â†’ "Discard all local changes and match remote main"
   * - curl -s url | jq '.data[]' â†’ "Fetch JSON from URL and extract data array elements"
   */
  description?: string;
  /**
   * Set to true to run this command in the background.
   */
  run_in_background?: boolean;
  /**
   * Set this to true to dangerously override sandbox mode and run commands without sandboxing.
   */
  dangerouslyDisableSandbox?: boolean;
}
export interface TaskOutputInput {
  /**
   * The task ID to get output from
   */
  task_id: string;
