JsonLineBuffer(agent, (line) => this.parseLine(line));
        this.onEvent = onEvent;
        this.onMalformed = 
onMalformed;
        this.rootPath = rootPath;
        this.turnStarted = false;
    }

    push(chunk) {
       
 this.lines.push(chunk);
    }

    finish() {
        this.lines.finish();
    }

    parseLine(line) {
      
  let event;
        try {
            event = JSON.parse(line);
        } catch {
            
this.onMalformed(line);
            return;
        }
        if (!event || typeof event !== 'object' || 
Array.isArray(event)) {
            this.onMalformed(line);
            return;
        }

        const 
missingSession = isMissingSession(this.agent, event, this.turnStarted);
        this.turnStarted = this.turnStarted 
|| isTurnEvent(this.agent, event);
        const assistantText = this.agent === 'codex' ? codexAssistantText(event) : 
claudeAssistantText(event);
        this.onEvent({
            assistantText,
            changedPaths: 
providerChangedPaths(this.agent, event, this.rootPath),
            conversationId: 
providerConversationId(this.agent, event),
            errorText: providerErrorText(this.agent, event),
            
missingSession,
            transcriptEvents: providerTranscriptEvents(this.agent, event),
            turnStarted: 
this.turnStarted,
            usage: providerUsage(this.agent, event),
        });
    }
}

function 
createAgentProviderProtocolParser(agent, onEvent, onMalformed, rootPath) {
    if (agent !== 'codex' && agent !== 
'claude') return null;

    return new AgentProviderProtocolParser(agent, onEvent, onMalformed, 
rootPath);
}

