import { createRequire } from 'node:module';
import path from 
'node:path';
import { describe, expect, it, vi } from 'vitest';

const require = 
createRequire(import.meta.url);
const { ActionAgentExecutor } = require('./action_agent_executor');

const action = 
{ agent: 'codex', id: 'main', label: 'Main', model: 'gpt-5.5', prompt: 'Review {{card-file}}', type: 'agent' };
const 
cardContext = { cardInternalId: 'card-1', file: 'design/card.md', kind: 'card' };
const project = { branch: 'main', 
rootPath: 'C:/repo' };

function conversation(overrides = {}) {
    return {
        cardInternalId: 
cardContext.cardInternalId,
        cardPath: cardContext.file,
        entries: [{ content: 'old answer', id: 'm1', 
kind: 'message', role: 'assistant', timestamp: '2026-01-01T00:00:00.000Z' }],
        id: 'conversation-1',
        
providerSessions: [],
        ...overrides,
    };
}

function createExecutor(overrides = {}) {
    const 
agentRunnerService = {
        start: vi.fn(async (_project, _request, _onEvent, onComplete) => {
            
onComplete(0, {
                conversation: { id: 'run-conversation' }, missingSession: false, reference: 
'run.json',
                stderr: '', stdout: 'done', turnStarted: true,
            });

            return { 
runId: 'active-run' };
        }),
        stop: vi.fn(),
    };
    const localGitService = { 
loadAgentConversation: vi.fn(async () => conversation()) };
    const executor = new ActionAgentExecutor({
        
agentConfigProvider: () => ({ agent: 'codex', agentProfiles: [], model: '' }),
        agentRunnerService,
        
localGitService,
        ...overrides,
    });

    return { agentRunnerService, executor, localGitService 
};
}

function executionInput(overrides = {}) {
    return {
        action,
        activityOrigin: { 
cardInternalId: 'card-1', kind: 'card' },
        context: cardContext,
        onActiveRunChange: vi.fn(),
        
onEvent: vi.fn(),
        project,
        projectFolder: 'design',
        primaryProject: project,
        
releasesFolder: 'design/releases',
        runInput: { extraPrompt: '' },
        signal: new 
AbortController().signal,
        ...overrides,
    };
}

