"content": "import { createRequire } from 'node:module';
import { describe, expect, it } from 'vitest';

const 
require = createRequire(import.meta.url);
const { createAgentStreamingAdapter } = 
require('./agent_streaming_adapter');

function harness(agent, providerConversationId = null) {
    const events = 
[];
    const runtimeEvents = [];
    const writes = [];
    const adapter = createAgentStreamingAdapter(
        
agent,
        (message) => writes.push(message),
        (event) => events.push(event),
        'C:\\repo',
    
    providerConversationId,
        (event) => runtimeEvents.push(event),
    );

    return { adapter, events, 
runtimeEvents, writes };
}

describe('ClaudeStreamingAdapter', () => {
    it('writes multiple user turns and 
treats each result as a turn boundary', async () => {
        const { adapter, events, writes } = 
harness('claude');

        await adapter.start('plan');
        await adapter.handleMessage({ session_id: 
'session-1', subtype: 'init', type: 'system' });
        await adapter.handleMessage({ message: { content: [{ text: 
'proposal', type: 'text' }] }, type: 'assistant' });
        await adapter.handleMessage({ total_cost_usd: 0.01, 
type: 'result', usage: { input_tokens: 4, output_tokens: 2 } });
        await adapter.sendMessage('approved');

   
     expect(writes).toEqual([
            { message: { content: 'plan', role: 'user' }, type: 'user' },
            
{ message: { content: 'approved', role: 'user' }, type: 'user' },
        ]);
        
expect(events).toContainEqual({ conversationId: 'session-1', type: 'sessionStarted' });
        
expect(events).toContainEqual({ content: 'proposal', type: 'assistant' });
        
expect(events.at(-1)).toMatchObject({ error: null, type: 'turnCompleted' });
    });

    it('correlates structured 
question answers through the Claude control protocol', async () => {
        const { adapter, events, writes } = 
harness('claude');
        const questions = [{ header: 'Confirm', options: [{ label: 'Yes' }], question: 'Proceed?' 
}];

        await adapter.handleMessage({
            request: {
                input: { questions },
          
      subtype: 'can_use_tool',
                tool_name: 'AskUserQuestion',
                tool_use_id: 
'tool-1',
            },
            request_id: 'request-1',
            type: 'control_request',
        });
   
     await adapter.answerQuestion('request-1', { 'claude-question-0': ['Yes'] });

        
expect(events).toContainEqual({
            questions: [{ ...questions[0], id: 'claude-question-0' }],
            
requestId: 'request-1',
            type: 'question',
        });
        expect(writes.at(-1)).toEqual({
         
   response: {
                request_id: 'request-1',
                response: {
                    behavior: 
'allow',
                    toolUseID: 'tool-1',
                    updatedInput: { answers: { 'Proceed?': ['Yes'] 
}, questions },
                },
                subtype: 'success',
            },
            type: 
'control_response',
        });
    });

    it('maps root-confined file changes and tool transcript events', 
async () => {
        const { adapter, events } = harness('claude');

        await adapter.handleMessage({
       
     message: {
                content: [
                    { input: { file_path: 'design\\feature.md' }, name: 
'Write', type: 'tool_use' },
                    { input: { file_path: 'C:\\outside\\secret.md' }, name: 'Edit', 
type: 'tool_use' },
                ],
            },
            type: 'assistant',
        });
        await 
adapter.handleMessage({
            message: { content: [{ content: 'written', tool_use_id: 'tool-1', type: 
